using System;using System.Collections;using System.Linq;using System.Reflection;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;
namespace DragonTower.Editor {
[InitializeOnLoad] public static class AqueductValidation {
 const string Flag="AqueductQA",Key="DragonTower.Test.Aqueduct",Out="C:/Users/PC/Documents/Codex/Aqueduct-20261011/";static CollectionFlow flow;static ContentDatabase db;static BattleSkin skin;static IEnumerator cases;static double next;
 static AqueductValidation(){if(SessionState.GetBool(Flag,false))EditorApplication.update+=Tick;}
 public static void Run(){Environment.SetEnvironmentVariable("DRAGON_TOWER_TEST_SAVE",Key);PlayerPrefs.DeleteKey(Key+".A");PlayerPrefs.DeleteKey(Key+".B");SessionState.SetBool(Flag,true);AssetDatabase.ImportAsset("Assets/Resources/PixelBattleSkin.asset",ImportAssetOptions.ForceUpdate);Debug.Log("SKIN_DUMP "+JsonUtility.ToJson(Resources.Load<BattleSkin>("PixelBattleSkin")));EditorSceneManager.OpenScene("Assets/Scenes/Battle.unity");EditorApplication.EnterPlaymode();}
 static void Check(bool b,string message){if(!b)throw new Exception(message);Debug.Log("AQUEDUCT_CHECK "+message);}
 static object Call(string n,params object[] a)=>typeof(CollectionFlow).GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(flow,a);
 static void Capture(string n)=>typeof(AugmentPresentationValidation).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{Out+n+".png"});
 static void Assign(TowerRun r)=>typeof(CollectionFlow).GetField("towerRun",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(flow,r);
 static void Set(int floor,TowerRoomKind kind,bool chosen=true){flow.ShowLobby();var d=flow.Session.Selected;var r=new TowerRun(d.maxHP,0,1,d.elementType,d.alternateSkillElement,d.StableId,d);r.AttachInstance(flow.Session.Profile.selectedInstanceId);var s=r.Capture();s.Floor=floor;s.choices=kind==TowerRoomKind.Boss?new[]{kind}:new[]{kind,TowerRoomKind.Gold};r=TowerRun.Restore(s,db);if(chosen)r.BeginFloorRoom(0,18421);Assign(r);}
 static void Scenery(EnvironmentScreen s){var image=UnityEngine.Object.FindObjectsByType<Image>(FindObjectsSortMode.None).First(x=>x.name=="Room scenery"&&x.gameObject.activeInHierarchy);Check(image.sprite==skin.BackgroundForScreen(flow.CurrentRun.Floor,s),"scenery "+flow.ScreenName);}
 static IEnumerator Cases(){
 Check(skin.EntranceForFloor(11)!=null,"region configuration loaded"); foreach(EnvironmentScreen s in Enum.GetValues(typeof(EnvironmentScreen)))foreach(int f in new[]{11,20})Check(skin.BackgroundForScreen(f,s)!=null&&AssetDatabase.GetAssetPath(skin.BackgroundForScreen(f,s)).Contains("/Aqueduct/"),"route "+f+" "+s);
 foreach(int f in new[]{1,10})foreach(EnvironmentScreen s in Enum.GetValues(typeof(EnvironmentScreen)))Check(skin.BackgroundForScreen(f,s)==skin.environmentBackgrounds[0].Get(s),"dungeon preserved "+f+" "+s);
 for(int f=51;f<=80;f++){Check(skin.BackgroundForFloor(f)==(f<=30?skin.forgeDepthsBackground:skin.upperTowerBackgrounds[(f-31)/10]),"upper battle preserved "+f);Check(skin.BackgroundForScreen(f,EnvironmentScreen.Item)==Resources.Load<Sprite>("UI/treasure-chamber"),"upper reward preserved "+f);}
 var fallback=ScriptableObject.CreateInstance<BattleSkin>();fallback.towerBackground=skin.towerBackground;fallback.environmentBackgrounds=new[]{new EnvironmentBackgroundSet{firstFloor=11,lastFloor=20}};Check(fallback.BackgroundForScreen(11,EnvironmentScreen.Item)!=null&&fallback.BackgroundForFloor(11)==skin.towerBackground,"missing art fallback");UnityEngine.Object.Destroy(fallback);
 Check(JsonUtility.FromJson<PlayerProfile>("{\"version\":1}").discoveredRegions==null||JsonUtility.FromJson<PlayerProfile>("{\"version\":1}").discoveredRegions.Count==0,"legacy discovery optional");
 Set(11,TowerRoomKind.Monster);Call("StartCurrentBattle");yield return .3f;Capture("battle");
 Set(20,TowerRoomKind.Boss);Call("StartCurrentBattle");yield return .3f;Capture("boss-battle");
 Set(12,TowerRoomKind.Item);Call("ShowTreasureChamber");Scenery(EnvironmentScreen.Item);yield return .3f;Capture("item");flow.RoomButton.onClick.Invoke();flow.RoomButton.onClick.Invoke();yield return 2f;Check(flow.CurrentRun.ChestOpened&&flow.ChoiceButtons.Length==3,"chest reveal three choices");var ids=string.Join(",",flow.CurrentRun.ChestRewardIds);Call("SaveProgress");flow.ShowLobby();flow.ResumeRun();Check(flow.CurrentRun.ChestOpened&&string.Join(",",flow.CurrentRun.ChestRewardIds)==ids,"chest resume no reroll");
 Set(13,TowerRoomKind.Gold);Call("ShowGoldRoom");Scenery(EnvironmentScreen.Item);yield return .3f;Capture("gold");flow.RoomButton.onClick.Invoke();flow.RoomButton.onClick.Invoke();yield return 1.25f;Check(flow.CurrentRun.Gold==50&&flow.CurrentRun.RewardClaimed,"gold once");
 Set(14,TowerRoomKind.Recovery);flow.CurrentRun.SyncHealth(1,false);Call("ShowRecoveryRoom");Scenery(EnvironmentScreen.Item);yield return .3f;Capture("recovery");flow.RoomButton.onClick.Invoke();yield return 1.25f;Check(flow.CurrentRun.CurrentHP==flow.CurrentRun.MaxHP&&flow.CurrentRun.RewardClaimed,"recovery full");
 Set(15,TowerRoomKind.Nest);Call("ShowNestRoom");Scenery(EnvironmentScreen.Item);yield return .3f;Capture("nest");int owned=flow.Session.Profile.dragons.Count;flow.RoomButton.onClick.Invoke();flow.RoomButton.onClick.Invoke();yield return 1.3f;Check(flow.Session.Profile.dragons.Count==owned+1&&flow.CurrentRun.RewardClaimed,"nest once");
 Set(12,TowerRoomKind.Item,false);Call("ShowTowerChoices");Scenery(EnvironmentScreen.Stairs);yield return .3f;Capture("stairs");Check(flow.RoomButton.GetComponent<RectTransform>().anchoredPosition==new Vector2(-103,-225),"unchanged door target");flow.RoomButton.onClick.Invoke();yield return 1.4f;Check(flow.CurrentRun.Floor==12&&flow.ScreenName=="아이템방","door selection");
 Set(20,TowerRoomKind.Boss,false);Call("ShowTowerChoices");Scenery(EnvironmentScreen.BossEntrance);yield return .3f;Capture("boss-entrance");
 Set(10,TowerRoomKind.Boss);var r=flow.CurrentRun;var cfg=FloorProgressionConfig.Load();r.BeginFloorCombat(cfg,50);Check(r.CompleteFloorCombat(r.MaxHP,cfg),"boss victory settles");Check(!r.CompleteFloorCombat(r.MaxHP,cfg),"boss duplicate reward blocked");r.CompleteBattleRewards();r.AcknowledgeExperience();var snapshot=r.Capture();snapshot.PendingLevelAugments=0;snapshot.PendingEvolutionStage=0;Assign(TowerRun.Restore(snapshot,db));int gold=flow.CurrentRun.Gold;Call("AdvanceFloor");int score=flow.CurrentRun.Progress.score;Call("AdvanceFloor");Check(flow.CurrentRun.Floor==11&&flow.ScreenName=="구역 진입","advance exactly once floor="+flow.CurrentRun.Floor+" screen="+flow.ScreenName+" phase="+flow.CurrentRun.Phase+" active="+flow.CurrentRun.Active);yield return .9f;Capture("transition-door");flow.ShowLobby();flow.ResumeRun();Check(flow.CurrentRun.Floor==11&&flow.ScreenName=="구역 진입","interrupted entrance resumed");yield return 2.1f;Capture("transition-stairs");yield return 1.4f;Capture("transition-title");yield return 1f;
 Check(flow.CurrentRun.Floor==11&&flow.ScreenName=="다음 길 선택","entrance completes floor11");Check(flow.CurrentRun.Gold==gold&&flow.CurrentRun.Progress.score==score,"presentation no duplicate gold or score");Check(flow.Session.HasDiscoveredRegion("ancient-aqueduct"),"discovery saved");var restored=new CollectionSession(new ProfileStore(Key),db.dragons);Check(restored.HasDiscoveredRegion("ancient-aqueduct"),"discovery reload");flow.ShowLobby();flow.ResumeRun();Check(flow.ScreenName=="다음 길 선택"&&flow.CurrentRun.Floor==11,"completed entrance skip resume");Set(11,TowerRoomKind.Item,false);Call("ShowTowerChoices");Check(flow.ScreenName=="다음 길 선택","discovered skip new run");
 Debug.Log("AQUEDUCT_ALL_OK");yield return .1f;
 }
 static void Tick(){try{if(!EditorApplication.isPlaying||EditorApplication.timeSinceStartup<next)return;if(flow==null){flow=UnityEngine.Object.FindFirstObjectByType<CollectionFlow>();if(flow?.Session==null){flow=null;return;}if(flow.Session.Selected==null)flow.Session.Hatch(0);db=ContentDatabase.Load();skin=Resources.Load<BattleSkin>("PixelBattleSkin");Screen.SetResolution(480,850,false);cases=Cases();}if(cases.MoveNext()){next=EditorApplication.timeSinceStartup+(float)cases.Current;return;}SessionState.SetBool(Flag,false);AncientUiValidation.Build();}catch(Exception e){Debug.LogException(e);SessionState.SetBool(Flag,false);EditorApplication.Exit(1);}}
}}


